script:
const phanHe = ctx.val('phan_he', 'maintenance').trim().toLowerCase() || 'maintenance';
const dlg = page.getByRole('dialog');

await step('Điều hướng vào Thiết Lập -> Nhân Viên Phụ Trách', async () => {
  if (!page.url().includes(`/${phanHe}/`)) {
    await page.goto(`https://tasks.zuizui.io/${phanHe}/dashboard`, { waitUntil: 'domcontentloaded' });
  }
  await page.waitForLoadState('networkidle', { timeout: 25000 }).catch(() => {});
  const setupBtn = page.getByRole('button', { name: 'Thiết Lập' });
  if (await setupBtn.isVisible().catch(() => false)) await setupBtn.click();
  const link = page.getByRole('link', { name: 'Nhân Viên Phụ Trách' });
  await link.waitFor({ timeout: 10000 });
  await link.click();
  await page.waitForLoadState('networkidle', { timeout: 25000 }).catch(() => {});
});

await step('Kiểm tra bảng danh sách nhân viên phụ trách', async () => {
  const txt = await page.locator('body').innerText();
  for (const h of ['Nhân viên phụ trách', 'Mô tả ngắn', 'Thao tác']) {
    assert(txt.includes(h), 'Thiếu cột trên bảng Nhân viên phụ trách: ' + h);
  }
});

await step('Kiểm tra mở/đóng dialog Chỉnh sửa và Xóa nhân viên', async () => {
  const editIcon = page.locator('.box-icon-table').first();
  if (await editIcon.isVisible().catch(() => false)) {
    await editIcon.click();
    await dlg.waitFor({ timeout: 8000 });
    assert(await dlg.getByText('Chỉnh sửa thông tin').isVisible().catch(() => false), 'Không thấy tiêu đề Chỉnh sửa thông tin');
    await page.getByRole('button', { name: 'Đóng' }).click();
    await dlg.waitFor({ state: 'hidden', timeout: 8000 }).catch(() => {});
  }

  const delIcon = page.locator('.svg-next-icon.svg-next-icon-size-16').first();
  if (await delIcon.isVisible().catch(() => false)) {
    await delIcon.click();
    await dlg.waitFor({ timeout: 8000 });
    assert(await page.getByText(/Bạn có chắc chắn muốn xoá/).isVisible().catch(() => false), 'Không thấy thông báo xác nhận xóa');
    await page.getByRole('button', { name: 'Đóng' }).click();
    await dlg.waitFor({ state: 'hidden', timeout: 8000 }).catch(() => {});
  }
});

await step('Kiểm tra mở/đóng dialog Thêm nhân viên phụ trách', async () => {
  const addBtn = page.getByRole('button', { name: 'Thêm nhân viên phụ trách' });
  await addBtn.waitFor({ timeout: 10000 });
  await addBtn.click();
  await dlg.waitFor({ timeout: 8000 });
  await page.getByRole('heading', { name: 'Thêm nhân viên phụ trách' }).waitFor({ timeout: 8000 });
  assert(await page.getByRole('textbox', { name: 'Chọn người phụ trách' }).isVisible().catch(() => false), 'Thiếu ô Chọn người phụ trách');
  await page.getByRole('button', { name: 'Đóng' }).click();
  ctx.log('Đã kiểm tra đầy đủ màn hình Nhân Viên Phụ Trách.');
});
